static char g_amd_config_dir[MAX_PATH * 4];
static int g_amd_config_owned;

static void amd_config_prepare_env(void)
{
    char existing[MAX_PATH * 4];
    char module[MAX_PATH * 4];
    char *slash;
    DWORD n;
    if (GetEnvironmentVariableA("AMD_CONFIG_DIR", existing, sizeof existing)) return;
    if (!g_self_module || !GetModuleFileNameA(g_self_module, module, sizeof module)) return;
    slash = strrchr(module, '\\');
    if (!slash) return;
    *slash = 0;
    if (_snprintf(g_amd_config_dir, sizeof g_amd_config_dir, "%s\\amdcfg", module) < 0) {
        g_amd_config_dir[0] = 0; return;
    }
    g_amd_config_dir[sizeof g_amd_config_dir - 1] = 0;
    n = GetEnvironmentVariableA("AMD_CONFIG_DIR", existing, sizeof existing);
    if (!n && SetEnvironmentVariableA("AMD_CONFIG_DIR", g_amd_config_dir))
        g_amd_config_owned = 1;
}

static int g_log_on;
/* Performance runs can disable shim telemetry without disabling any
   translation or state-replay branch.  The wrapper is deliberately limited
   to append/write operations under the shim log directory; read-mode file
   access and game-facing GL behavior are untouched. */
static int g_telemetry_quiet;
static FILE *shim_fopen(const char *path, const char *mode)
{
    if (g_telemetry_quiet && path && mode &&
        (mode[0] == 'a' || mode[0] == 'w') &&
        strstr(path, "C:\\fgo\\_tools\\glshim\\") == path &&
        strstr(path, "C:\\fgo\\_tools\\glshim\\perf_timing_v1.log") != path)
        return NULL;
    return fopen(path, mode);
}
