static GLuint g_bound_draw_framebuffer;
static GLint g_viewport_x, g_viewport_y;
static GLsizei g_viewport_w, g_viewport_h;

/* Low-perturbation API census. Resolution is recorded once per requested
   symbol and calls are aggregated in memory. The census deliberately avoids
   file I/O from hot wrappers; compact deltas flush at frame boundaries. */
enum {
    API_GROUP_NV_BINDLESS = 0,
    API_GROUP_NV_UNIFIED,
    API_GROUP_NV_ADDRESS,
    API_GROUP_WGL_DX,
    API_GROUP_SHADER_PROGRAM,
    API_GROUP_FEEDBACK_COPY,
    API_GROUP_DRAW_SUBMISSION,
    API_GROUP_TEXTURE_IMAGE,
    API_GROUP_OTHER_NV,
    API_GROUP_OTHER_EXTENSION,
    API_GROUP_CORE,
    API_GROUP_COUNT
};

enum {
    API_RES_HOOK = 1,
    API_RES_REAL = 2,
    API_RES_ARB_FALLBACK = 3,
    API_RES_STUB = 4,
    API_RES_MISSING = 5
};

enum {
    API_DISABLE_SHADER_REWRITE = 1u << 0,
    API_DISABLE_UNIFIED_MEMORY = 1u << 1,
    API_DISABLE_BINDLESS = 1u << 2,
    API_DISABLE_FEEDBACK = 1u << 3,
    API_DISABLE_DEFERRED_LIGHT = 1u << 4
};

#define API_CENSUS_MAX 512
typedef struct {
    char name[96];
    unsigned group;
    unsigned lookups;
    unsigned calls;
    unsigned resolution;
    unsigned reported_calls;
} api_census_rec;

static int g_api_census_on;
static int g_nv_dispatch_inventory_on;
static volatile LONG g_nv_dispatch_log_mask;
static volatile LONG g_nv_dispatch_unhandled_lock;
static unsigned g_nv_dispatch_unhandled_count;
static char g_nv_dispatch_unhandled_names[16][96];
static unsigned g_api_disable_mask;
static api_census_rec g_api_census[API_CENSUS_MAX];
static unsigned g_api_census_count;
static unsigned long long g_api_census_group_calls[API_GROUP_COUNT];
static unsigned long long g_api_census_last_flush_frame;
static int g_api_census_inventory_written;
static unsigned g_api_census_inventory_count;
static volatile LONG g_api_census_flush_busy;

static const char *api_census_group_name(unsigned group)
{
    static const char *names[API_GROUP_COUNT] = {
        "nv_bindless", "nv_unified_memory", "nv_address_range",
        "wgl_dx_interop", "shader_program", "feedback_copy",
        "draw_submission", "texture_image", "other_nv",
        "other_extension", "core"
    };
    return group < API_GROUP_COUNT ? names[group] : "unknown";
}

static unsigned api_census_classify(const char *name)
{
    if (!name) return API_GROUP_CORE;
    if (strncmp(name, "wglDX", 5) == 0) return API_GROUP_WGL_DX;
    if (strstr(name, "Bindless") || strstr(name, "Handleui64") ||
        strstr(name, "TextureHandle") || strstr(name, "TextureSamplerHandle") ||
        strstr(name, "ImageHandle"))
        return API_GROUP_NV_BINDLESS;
    if (strstr(name, "MakeNamedBuffer") ||
        strstr(name, "GetNamedBufferParameterui64") ||
        strstr(name, "GetBufferParameterui64") ||
        strstr(name, "BufferAddressRange") ||
        strstr(name, "GetIntegerui64"))
        return API_GROUP_NV_ADDRESS;
    if (strstr(name, "BufferAddress") || strstr(name, "Unified") ||
        (strstr(name, "VertexAttrib") && strstr(name, "NV")))
        return API_GROUP_NV_UNIFIED;
    if (strstr(name, "Shader") || strstr(name, "Program"))
        return API_GROUP_SHADER_PROGRAM;
    if (strstr(name, "Framebuffer") || strstr(name, "Copy") ||
        strstr(name, "Blit") || strstr(name, "Feedback"))
        return API_GROUP_FEEDBACK_COPY;
    if (strstr(name, "Draw")) return API_GROUP_DRAW_SUBMISSION;
    if (strstr(name, "Texture") || strstr(name, "Image"))
        return API_GROUP_TEXTURE_IMAGE;
    if (strstr(name, "NV")) return API_GROUP_OTHER_NV;
    if (strstr(name, "ARB") || strstr(name, "EXT") ||
        strncmp(name, "wgl", 3) == 0)
        return API_GROUP_OTHER_EXTENSION;
    return API_GROUP_CORE;
}

static api_census_rec *api_census_slot(const char *name, unsigned group)
{
    if (!g_api_census_on || !name || !*name) return NULL;
    for (unsigned i = 0; i < g_api_census_count; i++) {
        if (strcmp(g_api_census[i].name, name) == 0) return &g_api_census[i];
    }
    if (g_api_census_count >= API_CENSUS_MAX) return NULL;
    api_census_rec *r = &g_api_census[g_api_census_count++];
    memset(r, 0, sizeof *r);
    strncpy(r->name, name, sizeof(r->name) - 1);
    r->group = group < API_GROUP_COUNT ? group : api_census_classify(name);
    return r;
}

static void api_census_lookup(const char *name, unsigned resolution, PROC p)
{
    (void)p;
    if (!g_api_census_on || !name) return;
    api_census_rec *r = api_census_slot(name, api_census_classify(name));
    if (!r) return;
    r->lookups++;
    if (r->resolution == 0) r->resolution = resolution;
}

static void api_census_group_call(unsigned group)
{
    if (!g_api_census_on || group >= API_GROUP_COUNT) return;
    g_api_census_group_calls[group]++;
}

static void api_census_symbol_call(const char *name, unsigned group)
{
    if (!g_api_census_on) return;
    api_census_group_call(group);
    api_census_rec *r = api_census_slot(name, group);
    if (r) r->calls++;
}

static const char *api_census_resolution_name(unsigned resolution)
{
    switch (resolution) {
    case API_RES_HOOK: return "hook";
    case API_RES_REAL: return "real";
    case API_RES_ARB_FALLBACK: return "arb_fallback";
    case API_RES_STUB: return "stub";
    case API_RES_MISSING: return "missing";
    default: return "unknown";
    }
}

static void api_census_flush(int force)
{
    if (!g_api_census_on) return;
    if (!force && g_frame_count < 60) return;
    if (!force && g_frame_count == g_api_census_last_flush_frame) return;
    if (!force && (g_frame_count % 300) != 0 && g_api_census_inventory_written) return;
    if (InterlockedExchange(&g_api_census_flush_busy, 1) != 0) return;

    FILE *f = fopen("C:\\fgo\\_tools\\glshim\\api_census_v1.log", "a");
    if (f) {
        if (!g_api_census_inventory_written) {
            fprintf(f, "pid=%lu event=inventory frame=%llu entries=%u\n",
                    (unsigned long)GetCurrentProcessId(),
                    (unsigned long long)g_frame_count, g_api_census_count);
            g_api_census_inventory_written = 1;
        }
        for (unsigned i = g_api_census_inventory_count;
             i < g_api_census_count; i++) {
            api_census_rec *r = &g_api_census[i];
            fprintf(f, "symbol=%s group=%s lookups=%u resolution=%s\n",
                    r->name, api_census_group_name(r->group), r->lookups,
                    api_census_resolution_name(r->resolution));
            r->reported_calls = r->calls;
        }
        g_api_census_inventory_count = g_api_census_count;
        fprintf(f, "pid=%lu event=summary frame=%llu\n",
                (unsigned long)GetCurrentProcessId(),
                (unsigned long long)g_frame_count);
        for (unsigned i = 0; i < API_GROUP_COUNT; i++)
            fprintf(f, "group=%s calls=%llu\n", api_census_group_name(i),
                    (unsigned long long)g_api_census_group_calls[i]);
        for (unsigned i = 0; i < g_api_census_count; i++) {
            api_census_rec *r = &g_api_census[i];
            if (r->calls == r->reported_calls) continue;
            fprintf(f, "delta symbol=%s group=%s calls=%u\n", r->name,
                    api_census_group_name(r->group), r->calls);
            r->reported_calls = r->calls;
        }
        fclose(f);
    }
    g_api_census_last_flush_frame = g_frame_count;
    InterlockedExchange(&g_api_census_flush_busy, 0);
}

static PROC api_census_resolved(const char *name, unsigned resolution, PROC p)
{
    api_census_lookup(name, resolution, p);
    return p;
}

static const char *nv_to_arb(const char *name)
{
    static const struct { const char *nv; const char *arb; } map[] = {
        {"glGetTextureHandleNV", "glGetTextureHandleARB"},
        {"glGetTextureSamplerHandleNV", "glGetTextureSamplerHandleARB"},
        {"glMakeTextureHandleResidentNV", "glMakeTextureHandleResidentARB"},
        {"glMakeTextureHandleNonResidentNV", "glMakeTextureHandleNonResidentARB"},
        {"glGetImageHandleNV", "glGetImageHandleARB"},
        {"glMakeImageHandleResidentNV", "glMakeImageHandleResidentARB"},
        {"glMakeImageHandleNonResidentNV", "glMakeImageHandleNonResidentARB"},
        {"glUniformHandleui64NV", "glUniformHandleui64ARB"},
        {"glUniformHandleui64vNV", "glUniformHandleui64vARB"},
        {"glProgramUniformHandleui64NV", "glProgramUniformHandleui64ARB"},
        {"glProgramUniformHandleui64vNV", "glProgramUniformHandleui64vARB"},
        {"glIsTextureHandleResidentNV", "glIsTextureHandleResidentARB"},
        {"glIsImageHandleResidentNV", "glIsImageHandleResidentARB"},
        {"glVertexAttribL1ui64NV", "glVertexAttribL1ui64ARB"},
        {"glVertexAttribL1ui64vNV", "glVertexAttribL1ui64vARB"},
        {"glGetVertexAttribLui64vNV", "glGetVertexAttribLui64vARB"},
    };
    size_t i;
    for (i = 0; i < sizeof(map) / sizeof(map[0]); i++) {
        if (strcmp(name, map[i].nv) == 0) return map[i].arb;
    }
    return NULL;
}

/* AMD exposes ARB_bindless_texture but not the NVIDIA entry-point names used
   by the game.  Keep a small handle table so the probe can identify which GL
   texture a 64-bit sampler value refers to when the draw has no ordinary
   texture-unit binding. */
#define BINDLESS_HANDLE_MAX 4096
#define BINDLESS_SAMPLER_HANDLE_CACHE_SLOTS 8192
static void perf_rs_uniform4(GLuint program, GLint location, GLsizei count, const float *values);
static void perf_rs_uniform_sampler(GLuint program, GLint location, GLuint64 value, int handle);
static int perf_rs_begin(void);
static void perf_rs_indirect_begin(GLint location, GLint draw_id);
static void perf_rs_upload_gpu_target(GLenum target, GLuint buffer);
static void perf_rs_end(void);
static void perf_rs_indirect_batch_begin(GLsizei count);
static void perf_rs_indirect_batch_end(void);
static PROC perf_rs_wrapper(const char *name);
static void perf_rs_context_change(HGLRC context);
static void perf_rs_invalidate_units(GLuint first, GLsizei count);
static void bindless_sampler_handle_cache_invalidate(void);
static void bindless_sampler_handle_cache_forget_texture(GLsizei count,
                                                         const GLuint *textures);
static void bindless_sampler_handle_cache_forget_sampler(GLsizei count,
                                                         const GLuint *samplers);
#define BINDLESS_UNIFORM_MAX 8192
#define BINDLESS_MAP_MAX 128
#define BINDLESS_BUFFER_NAME_MAX (1u << 20)
/* The bindless probe runs on the application's draw/update hot paths.  Keep
   its work proportional to the handles actually observed instead of walking
   the fixed diagnostic tables for every draw. */
#define BINDLESS_TEXTURE_PROBE_MAX_SCAN_BYTES (256u * 1024u)
typedef struct {
    GLuint64 handle;
    GLuint texture;
    GLuint sampler;
    GLuint buffer;
    GLintptr buffer_offset;
    GLenum buffer_target;
    GLuint buffer_program;
    unsigned get_calls;
    unsigned resident;
    unsigned nonresident;
    unsigned char resident_known;
    unsigned char resident_state;
    unsigned buffer_hits;
    unsigned long long last_draw_frame;
    unsigned long long first_get_frame;
    unsigned long long last_get_frame;
} bindless_handle_rec;

typedef struct {
    GLuint program;
    GLint location;
    GLuint64 handle;
    unsigned array_index;
    unsigned updates;
    unsigned long long last_draw_frame;
} bindless_uniform_rec;

static bindless_handle_rec g_bindless_handles[BINDLESS_HANDLE_MAX];

/* AMD may synchronously prepare driver state on every sampler-handle query.
   A live texture/sampler pair keeps the same handle until either object is
   deleted or the current GL context changes. */
typedef struct {
    GLuint texture;
    GLuint sampler;
    GLuint64 handle;
} bindless_sampler_handle_cache_rec;
static bindless_sampler_handle_cache_rec
    g_bindless_sampler_handle_cache[BINDLESS_SAMPLER_HANDLE_CACHE_SLOTS];
static unsigned long long g_perf_sampler_handle_hits;
static unsigned long long g_perf_sampler_handle_queries;
#define BINDLESS_SAMPLER_HANDLE_CACHE_PROBES 8

static unsigned bindless_sampler_handle_cache_hash(GLuint texture, GLuint sampler)
{
    uint32_t h = texture * 0x9e3779b1u ^ sampler * 0x85ebca6bu;
    h ^= h >> 16;
    return h & (BINDLESS_SAMPLER_HANDLE_CACHE_SLOTS - 1);
}

static GLuint64 bindless_sampler_handle_cache_find(GLuint texture, GLuint sampler)
{
    if (!texture || !sampler || g_bindless_onemip_sampler_bake_on ||
        g_battle_load_trace_on || g_battle_texture_boundary_on) return 0;
    unsigned home = bindless_sampler_handle_cache_hash(texture, sampler);
    /* A deleted entry can leave a hole before a live colliding pair.  Search
       the entire bounded neighborhood, including across the table's end. */
    for (unsigned i = 0; i < BINDLESS_SAMPLER_HANDLE_CACHE_PROBES; i++) {
        const bindless_sampler_handle_cache_rec *r =
            &g_bindless_sampler_handle_cache[
                (home + i) & (BINDLESS_SAMPLER_HANDLE_CACHE_SLOTS - 1)];
        if (r->texture == texture && r->sampler == sampler) return r->handle;
    }
    return 0;
}

static void bindless_sampler_handle_cache_store(GLuint texture, GLuint sampler,
                                                GLuint64 handle)
{
    if (!texture || !sampler || !handle || g_bindless_onemip_sampler_bake_on ||
        g_battle_load_trace_on || g_battle_texture_boundary_on) return;
    unsigned home = bindless_sampler_handle_cache_hash(texture, sampler);
    unsigned slot = home;
    int empty = 0;
    for (unsigned i = 0; i < BINDLESS_SAMPLER_HANDLE_CACHE_PROBES; i++) {
        unsigned index = (home + i) & (BINDLESS_SAMPLER_HANDLE_CACHE_SLOTS - 1);
        const bindless_sampler_handle_cache_rec *r =
            &g_bindless_sampler_handle_cache[index];
        if (r->texture == texture && r->sampler == sampler) {
            slot = index;
            break;
        }
        if (!r->handle && !empty) { slot = index; empty = 1; }
    }
    /* A full neighborhood still falls back to replacing the home slot.
       Eviction can cause a driver query, never a handle for a different pair. */
    g_bindless_sampler_handle_cache[slot] =
        (bindless_sampler_handle_cache_rec){texture, sampler, handle};
}

static void bindless_sampler_handle_cache_invalidate(void)
{
    memset(g_bindless_sampler_handle_cache, 0,
           sizeof g_bindless_sampler_handle_cache);
}

static void bindless_sampler_handle_cache_forget_texture(GLsizei count,
                                                         const GLuint *textures)
{
    if (count <= 0 || !textures) return;
    for (unsigned i = 0; i < BINDLESS_SAMPLER_HANDLE_CACHE_SLOTS; i++) {
        for (GLsizei j = 0; j < count; j++)
            if (textures[j] &&
                g_bindless_sampler_handle_cache[i].texture == textures[j]) {
                memset(&g_bindless_sampler_handle_cache[i], 0,
                       sizeof g_bindless_sampler_handle_cache[i]);
                break;
            }
    }
}

static void bindless_sampler_handle_cache_forget_sampler(GLsizei count,
                                                         const GLuint *samplers)
{
    if (count <= 0 || !samplers) return;
    for (unsigned i = 0; i < BINDLESS_SAMPLER_HANDLE_CACHE_SLOTS; i++) {
        for (GLsizei j = 0; j < count; j++)
            if (samplers[j] &&
                g_bindless_sampler_handle_cache[i].sampler == samplers[j]) {
                memset(&g_bindless_sampler_handle_cache[i], 0,
                       sizeof g_bindless_sampler_handle_cache[i]);
                break;
            }
    }
}
static bindless_uniform_rec g_bindless_uniforms[BINDLESS_UNIFORM_MAX];
typedef struct {
    GLuint buffer;
    GLenum target;
    GLintptr offset;
    GLsizeiptr length;
    GLbitfield access;
    unsigned char *ptr;
    unsigned active;
    unsigned sampler_wc_read;
} bindless_map_rec;
static bindless_map_rec g_bindless_maps[BINDLESS_MAP_MAX];
/* One-based map-slot index for the hot pointer-shadow lookup.  The lookup
   validates the slot and repairs stale entries because small test fixtures
   may clear g_bindless_maps directly. */
static unsigned char g_bindless_map_index[BINDLESS_BUFFER_NAME_MAX];
/* 0=unknown, 1=active/possibly indexed, 2=known absent.  Caching the absent
   result avoids rescanning all map records for ordinary unmapped buffers. */
static unsigned char g_bindless_map_state[BINDLESS_BUFFER_NAME_MAX];
static unsigned g_bindless_uniform_next;
static unsigned long long g_bindless_texture_probe_lines;
static unsigned long long g_bindless_texture_probe_draws;
static unsigned long long g_bindless_texture_probe_shared_draws;
static unsigned g_bindless_handle_count;
static unsigned g_bindless_uniform_count;
static unsigned long long g_bindless_texture_probe_last_scan_frame = ~0ULL;
static unsigned g_bindless_texture_probe_last_scan_handles;
static unsigned g_bindless_texture_probe_last_scan_uniforms;
static unsigned bindless_texture_probe_scan_buffer(const char *api, GLuint buffer,
                                                   GLenum target, GLintptr offset,
                                                   GLsizeiptr size, const void *data,
                                                   int shared_only);
static int bindless_texture_probe_handle_bound(const bindless_handle_rec *h);
static int perf_mapped_flush_shadow_copy(GLuint buffer, GLintptr offset,
                                         GLsizeiptr length, void *dst);
static const unsigned char *perf_mapped_flush_shadow_view(GLuint buffer,
                                                           GLintptr offset,
                                                           GLsizeiptr length);
