    battle_texture_boundary_before(texture, sampler, 1, (PROC)real);
    battle_observe_texture_handle("tex_handle_before", 3, texture, sampler, 0);
    if (real) g_perf_sampler_handle_queries++;
    GLuint64 h = real ? real(texture, sampler) : 0;
    battle_observe_texture_handle("tex_handle_after", 3, texture, sampler, h);
    battle_texture_boundary_after(texture, sampler, 1, h);
    bindless_texture_probe_record_handle("glGetTextureSamplerHandleNV", h, texture, sampler);
    bindless_sampler_handle_cache_store(texture, sampler, h);
