static void bindless_texture_probe_resident(const char *api, GLuint64 handle, int resident)
{
    if (!handle)
        return;
    bindless_handle_rec *r = bindless_handle_slot(handle);
    if (!r) return;
    if (resident) r->resident++;
    else r->nonresident++;
    r->resident_known = 1;
    r->resident_state = resident != 0;
    bindless_texture_probe_log("pid=%lu event=%s handle=0x%016llx tex=%u sampler=%u prog=%u frame=%llu",
                               (unsigned long)GetCurrentProcessId(),
                               resident ? "resident" : "nonresident",
                               (unsigned long long)handle, r->texture, r->sampler,
                               g_current_program, (unsigned long long)g_frame_count);
}

/* Residency belongs to a GL context.  Keep the deduplication state scoped to
   the current context so a handle observed in one context is never assumed
   resident after a context switch or release/rebind. */
static void bindless_texture_probe_context_change(HGLRC context)
{
    static HGLRC last_context;
    if (last_context == context)
        return;
    for (unsigned i = 0; i < g_bindless_handle_count; i++) {
        g_bindless_handles[i].resident_known = 0;
        g_bindless_handles[i].resident_state = 0;
    }
    last_context = context;
}

static int bindless_texture_probe_resident_known(GLuint64 handle)
{
    bindless_handle_rec *r = bindless_handle_find(handle);
    return r && r->resident_known && r->resident_state;
}

#define DEFINE_BINDLESS_RESIDENT_WRAPPER(name, fallback, resident_value) \
static void WINAPI wrap_##name(GLuint64 handle) \
{ \
    api_census_symbol_call(#name, API_GROUP_NV_BINDLESS); \
    static glMakeTextureHandleResident_t real; \
    if (!real) real = (glMakeTextureHandleResident_t)bindless_texture_probe_real(#name, fallback); \
    int skip = (resident_value) && g_perf_bindless_residency_dedup_on && \
        bindless_texture_probe_resident_known(handle); \
    if (real && !skip) BATTLE_OBSERVE_CALL("tex_residency",resident_value, \
        (int)handle,(int)(handle>>32),0,0,real(handle)); \
    bindless_texture_probe_resident(#name, handle, resident_value); \
}

