static void bindless_texture_probe_draw(const char *fn, GLsizei count, GLsizei primcount)
{
    api_census_group_call(API_GROUP_NV_BINDLESS);
    if (!g_bindless_texture_probe_on) return;
    g_bindless_texture_probe_draws++;
    if (g_bindless_texture_probe_draws <= 32 ||
        (g_bindless_texture_probe_draws % 1000) == 0) {
        bindless_texture_probe_log("pid=%lu event=draw_tick fn=%s frame=%llu prog=%u fb=%u viewport=%d,%d,%d,%d draws=%llu",
                                   (unsigned long)GetCurrentProcessId(), fn ? fn : "-",
                                   (unsigned long long)g_frame_count, g_current_program,
                                   g_bound_draw_framebuffer, g_viewport_x, g_viewport_y,
                                   g_viewport_w, g_viewport_h,
                                   (unsigned long long)g_bindless_texture_probe_draws);
    }
    /* A frame can contain thousands of draw calls.  The association state is
       stable for the frame, so repeating the two table walks on every draw
       only adds CPU cost without adding information.  Re-run if new handles
       or uniform records arrive later in the same frame. */
    if (g_bindless_texture_probe_last_scan_frame == g_frame_count &&
        g_bindless_texture_probe_last_scan_handles == g_bindless_handle_count &&
        g_bindless_texture_probe_last_scan_uniforms == g_bindless_uniform_count)
        return;
    g_bindless_texture_probe_last_scan_frame = g_frame_count;
    g_bindless_texture_probe_last_scan_handles = g_bindless_handle_count;
    g_bindless_texture_probe_last_scan_uniforms = g_bindless_uniform_count;

    for (unsigned i = 0; i < g_bindless_uniform_count; i++) {
        bindless_uniform_rec *u = &g_bindless_uniforms[i];
        if (!u->program || u->program != g_current_program || !u->handle ||
            u->last_draw_frame == g_frame_count)
            continue;
        bindless_handle_rec *h = bindless_handle_find(u->handle);
        if (!h) continue;
        u->last_draw_frame = g_frame_count;
        if (h->last_draw_frame == g_frame_count) continue;
        h->last_draw_frame = g_frame_count;
        int shared = h->texture ? idle_video_probe_is_shared_tex(h->texture) : 0;
        if (shared) g_bindless_texture_probe_shared_draws++;
        bindless_texture_probe_log("pid=%lu event=draw fn=%s frame=%llu prog=%u loc=%d index=%u handle=0x%016llx tex=%u sampler=%u shared=%d fb=%u viewport=%d,%d,%d,%d count=%d prim=%d",
                                   (unsigned long)GetCurrentProcessId(), fn ? fn : "-",
                                   (unsigned long long)g_frame_count, g_current_program,
                                   u->location, u->array_index, (unsigned long long)u->handle,
                                   h->texture, h->sampler, shared, g_bound_draw_framebuffer,
                                   g_viewport_x, g_viewport_y, g_viewport_w, g_viewport_h,
                                   (int)count, (int)primcount);
    }
    /* The game normally stores bindless sampler handles in PerScene and
       material UBO payloads rather than calling glUniformHandleui64*.  Match
       those recorded byte offsets against the ranges currently visible to
       the draw's program. */
    for (unsigned i = 0; i < g_bindless_handle_count; i++) {
        bindless_handle_rec *h = &g_bindless_handles[i];
        if (!h->handle || !h->buffer || !h->texture ||
            h->last_draw_frame == g_frame_count)
            continue;
        int bound = bindless_texture_probe_handle_bound(h);
        int shared = idle_video_probe_is_video_tex(h->texture);
        if (!bound && h->buffer_program != g_current_program && !shared)
            continue;
        h->last_draw_frame = g_frame_count;
        if (shared) g_bindless_texture_probe_shared_draws++;
        bindless_texture_probe_log("pid=%lu event=buffer_draw fn=%s frame=%llu prog=%u buf=%u target=0x%x off=%lld handle=0x%016llx tex=%u sampler=%u bound=%d shared=%d fb=%u viewport=%d,%d,%d,%d count=%d prim=%d",
                                   (unsigned long)GetCurrentProcessId(), fn ? fn : "-",
                                   (unsigned long long)g_frame_count, g_current_program,
                                   h->buffer, h->buffer_target, (long long)h->buffer_offset,
                                   (unsigned long long)h->handle, h->texture, h->sampler,
                                   bound, shared, g_bound_draw_framebuffer,
                                   g_viewport_x, g_viewport_y, g_viewport_w, g_viewport_h,
                                   (int)count, (int)primcount);
    }
}

