        keytex_log("glCompressedTextureSubImage2D tex=%u lvl=%d %d,%d %dx%d fmt=0x%x size=%d data=%p",
                   tex, level, x, y, w, h, format, size, data);
    battle_texture_upload_args(tex, level, x, y, 0, 1, 0, size, data);
