static idle_video_tex_rec *model_material_texture_find(GLuint tex)
{
    if (!tex) return NULL;
    for (unsigned i = 0;
         i < (unsigned)(sizeof g_idle_video_tex / sizeof g_idle_video_tex[0]);
         i++) {
        if (g_idle_video_tex[i].tex == tex) return &g_idle_video_tex[i];
    }
    return NULL;
}

static void mp4_p203_uniform_probe(const char *api, GLint location,
                                   GLsizei count, const float *value)
{
    if (g_telemetry_quiet || !g_idle_video_probe_on || g_current_program != 203 || !value ||
        count <= 0 || g_mp4_p203_uniform_probe_lines >= 512)
        return;
    unsigned n = (unsigned)count;
    if (n > 4) n = 4;
    struct candidate {
        uint32_t lo, hi, z, w;
        GLuint64 handle;
        bindless_handle_rec *record;
    } c[4];
    unsigned matches = 0;
    for (unsigned i = 0; i < n; i++) {
        memset(&c[matches], 0, sizeof c[matches]);
        memcpy(&c[matches].lo, value + i * 4 + 0, sizeof c[matches].lo);
        memcpy(&c[matches].hi, value + i * 4 + 1, sizeof c[matches].hi);
        memcpy(&c[matches].z, value + i * 4 + 2, sizeof c[matches].z);
        memcpy(&c[matches].w, value + i * 4 + 3, sizeof c[matches].w);
        c[matches].handle = ((GLuint64)c[matches].hi << 32) | c[matches].lo;
        c[matches].record = bindless_handle_find(c[matches].handle);
        if (!c[matches].record || !c[matches].record->texture ||
            !idle_video_probe_is_video_tex(c[matches].record->texture))
            continue;
        matches++;
    }
    if (!matches) return;
    FILE *f = fopen("C:\\fgo\\_tools\\glshim\\mp4_p203_uniform_probe_v2.log", "a");
    if (!f) return;
    fprintf(f, "pid=%lu frame=%llu api=%s prog=203 loc=%d count=%d matches=%u",
            (unsigned long)GetCurrentProcessId(),
            (unsigned long long)g_frame_count, api ? api : "?",
            location, (int)count, matches);
    for (unsigned i = 0; i < matches; i++) {
        bindless_handle_rec *h = c[i].record;
        idle_video_tex_rec *t = model_material_texture_find(h->texture);
        fprintf(f, " v%u=0x%08x,0x%08x,0x%08x,0x%08x handle=0x%016llx tex=%u sampler=%u shared=%d copy=%d size=%dx%d fmt=0x%x",
                i, c[i].lo, c[i].hi, c[i].z, c[i].w,
                (unsigned long long)c[i].handle, h->texture, h->sampler,
                idle_video_probe_is_shared_tex(h->texture),
                t ? (int)t->video_copy_destination : 0,
                t ? (int)t->width : 0, t ? (int)t->height : 0,
                t ? (unsigned)t->format : 0);
    }
    fputc('\n', f);
    fclose(f);
    g_mp4_p203_uniform_probe_lines++;
}

