#define NPR_COLOR_CORRECTION_PROBE_CAP 512
static int g_npr_color_correction_probe_on;
static unsigned long g_npr_color_correction_probe_lines;
static unsigned char g_npr_color_correction_probe_queried[65536];
static GLint g_npr_color_correction_probe_location[65536];
static GLint npr_color_correction_probe_location(GLuint program)
{
    static glGetUniformLocation_t real;
    if (!g_npr_color_correction_probe_on || program >= 65536)
        return -1;
    if (g_npr_color_correction_probe_queried[program])
        return g_npr_color_correction_probe_location[program];
    g_npr_color_correction_probe_queried[program] = 1;
    g_npr_color_correction_probe_location[program] = -1;
    if (!real)
        real = (glGetUniformLocation_t)trace_resolve("glGetUniformLocation");
    if (real)
        g_npr_color_correction_probe_location[program] =
            real(program, "g_npr_texture_color_correction");
    if (g_npr_color_correction_probe_lines < NPR_COLOR_CORRECTION_PROBE_CAP) {
        FILE *f = fopen(
            "C:\\fgo\\_tools\\glshim\\npr_color_correction_probe_v1.log", "a");
        if (f) {
            fprintf(f, "pid=%lu frame=%llu event=map prog=%u name=g_npr_texture_color_correction loc=%d\n",
                    (unsigned long)GetCurrentProcessId(),
                    (unsigned long long)g_frame_count, program,
                    (int)g_npr_color_correction_probe_location[program]);
            fclose(f);
        }
        g_npr_color_correction_probe_lines++;
    }
    return g_npr_color_correction_probe_location[program];
}
static void npr_color_correction_probe_value(
    const char *api, GLint location, GLsizei count, const float *value)
{
    if (!g_npr_color_correction_probe_on || !value || count <= 0)
        return;
    GLint wanted = npr_color_correction_probe_location(g_current_program);
    if (wanted < 0 || wanted != location ||
        g_npr_color_correction_probe_lines >= NPR_COLOR_CORRECTION_PROBE_CAP)
        return;
    FILE *f = fopen(
        "C:\\fgo\\_tools\\glshim\\npr_color_correction_probe_v1.log", "a");
    if (!f) return;
    fprintf(f, "pid=%lu frame=%llu event=value api=%s prog=%u loc=%d count=%d values=",
            (unsigned long)GetCurrentProcessId(),
            (unsigned long long)g_frame_count, api, g_current_program,
            (int)location, (int)count);
    int n = count > 4 ? 16 : count * 4;
    for (int i = 0; i < n; i++)
        fprintf(f, "%s%.7g", i ? "," : "", value[i]);
    fputc('\n', f);
    fclose(f);
    g_npr_color_correction_probe_lines++;
}
