    g_scene_color_origin_manual_frame = g_frame_count;
    g_scene_color_origin_window_active = 1;
    g_scene_color_origin_draw_lines = 0;
    g_scene_color_origin_texture_lines = 0;
    g_scene_color_origin_sample_lines = 0;
