static void texture_buffer_record(GLuint texture, GLenum internal_format,
                                  GLuint buffer, GLintptr offset,
                                  GLsizeiptr size, int ranged)
{
    perf_rs_upload_gpu_target(0x8C2A, buffer);
    if (texture < 65536) {
        texture_buffer_rec *rec = &g_texture_buffers[texture];
        rec->buffer = buffer;
        rec->internal_format = internal_format;
        rec->offset = offset;
        rec->size = size;
        rec->valid = buffer != 0;
        rec->ranged = ranged != 0;
    }
    if (g_tile_buffer_probe_on) {
        FILE *f = fopen("C:\\fgo\\_tools\\glshim\\tile_buffer_probe_v1.log", "a");
        if (f) {
            fprintf(f,
                    "pid=%lu frame=%llu event=texture_buffer tex=%u format=0x%x "
                    "buf=%u off=%lld size=%lld ranged=%d\n",
                    (unsigned long)GetCurrentProcessId(),
                    (unsigned long long)g_frame_count, texture, internal_format,
                    buffer, (long long)offset, (long long)size, ranged != 0);
            fclose(f);
        }
    }
}

