static void myroom_sc_snap_note_blit(GLint sx0, GLint sy0, GLint sx1, GLint sy1,
                                    GLint dx0, GLint dy0, GLint dx1, GLint dy1,
                                    GLbitfield mask)
{
    FILE *f;
    GLint src_w;
    GLint src_h;
    GLint dst_w;
    GLint dst_h;
    GLuint read_fb;
    GLuint draw_fb;
    GLuint src_c;
    GLuint dst_c;
    GLuint src_d;
    GLuint dst_d;
    float body[4];
    float hair[4];
    float zb;
    float zh;
    unsigned err;
    myroom_census_marker();
    if (!g_myroom_census_on)
        return;
    if (!(mask & 0x4000u))
        return;
    src_w = sx1 - sx0;
    src_h = sy1 - sy0;
    dst_w = dx1 - dx0;
    dst_h = dy1 - dy0;
    if (src_w < 1280 || src_h < 720 || src_w != dst_w || src_h != dst_h)
        return;
    read_fb = g_bound_read_framebuffer;
    draw_fb = g_bound_draw_framebuffer;
    if (read_fb == 0 || draw_fb == 0 || read_fb == draw_fb)
        return;
    src_c = (read_fb < 65536) ? g_fbo_attach[read_fb][0] : 0;
    dst_c = (draw_fb < 65536) ? g_fbo_attach[draw_fb][0] : 0;
    src_d = (read_fb < 65536) ? g_fbo_depth_attach[read_fb] : 0;
    dst_d = (draw_fb < 65536) ? g_fbo_depth_attach[draw_fb] : 0;
    if (!((read_fb == 105 && draw_fb == 95) ||
          (src_c == 99 && dst_c == 103)))
        return;
    g_myroom_sc_snap_n++;
    g_myroom_sc_snap_frame = g_frame_count;
    g_myroom_sc_snap_split = g_p700_sc_blit_last_split;
    g_myroom_sc_snap_err = (unsigned)g_p700_sc_blit_last_err;
    g_myroom_sc_snap_err2 = (unsigned)g_p700_sc_blit_last_err2;
    g_myroom_sc_snap_read = read_fb;
    g_myroom_sc_snap_draw = draw_fb;
    g_myroom_sc_snap_src_c = src_c;
    g_myroom_sc_snap_dst_c = dst_c;
    g_myroom_sc_snap_src_d = src_d;
    g_myroom_sc_snap_dst_d = dst_d;
    if (g_myroom_sc_snap_log_n >= 24)
        return;
    memset(body, 0, sizeof body);
    memset(hair, 0, sizeof hair);
    zb = -1.f;
    zh = -1.f;
    err = 0;
    if (dst_c) {
        unsigned e = 0;
        if (!myroom_census_named_read(dst_c, 816, 532, 1, 1, body, &e))
            err |= e;
        e = 0;
        if (!myroom_census_named_read(dst_c, 952, 802, 1, 1, hair, &e))
            err |= e;
    }
    if (dst_d) {
        unsigned e = 0;
        myroom_census_named_depth(dst_d, 816, 532, &zb, &e);
        e = 0;
        myroom_census_named_depth(dst_d, 952, 802, &zh, &e);
    }
    f = myroom_census_open();
    if (!f)
        return;
    fprintf(f,
            "pid=%lu frame=%llu event=sc_snap mask=0x%x read=%u/%u draw=%u/%u "
            "src_d=%u dst_d=%u split=%d err=0x%x err2=0x%x conv=%d "
            "u25=%u u26=%u extra_seen=%d "
            "sc_body=%.5g,%.5g,%.5g,%.5g sc_hair=%.5g,%.5g,%.5g,%.5g "
            "z95_body=%.5g z95_hair=%.5g n=%u errr=0x%x\n",
            (unsigned long)GetCurrentProcessId(),
            (unsigned long long)g_frame_count,
            (unsigned)mask, read_fb, src_c, draw_fb, dst_c,
            src_d, dst_d, g_myroom_sc_snap_split,
            g_myroom_sc_snap_err, g_myroom_sc_snap_err2,
            g_p700_sc_convert_path,
            g_tex_bind[25], g_tex_bind[26],
            g_myroom_hair_dd_extra_seen,
            body[0], body[1], body[2], body[3],
            hair[0], hair[1], hair[2], hair[3],
            zb, zh, g_myroom_sc_snap_n, err);
    fclose(f);
    g_myroom_sc_snap_log_n++;
}


