static void model_material_state_set_stencil_op(
    GLenum face, GLenum sfail, GLenum dpfail, GLenum dppass)
{
    if (face == 0x0404 || face == 0x0408) {
        g_model_material_stencil_sfail[0] = sfail;
        g_model_material_stencil_dpfail[0] = dpfail;
        g_model_material_stencil_dppass[0] = dppass;
    }
    if (face == 0x0405 || face == 0x0408) {
        g_model_material_stencil_sfail[1] = sfail;
        g_model_material_stencil_dpfail[1] = dpfail;
        g_model_material_stencil_dppass[1] = dppass;
    }
}

