static void nv_dispatch_log_resolution(unsigned index,
                                       const nv_dispatch_entry *entry,
                                       const char *status)
{
    if (!g_nv_dispatch_inventory_on || index >= 30) return;
    LONG bit = (LONG)(1u << index);
    if (InterlockedOr(&g_nv_dispatch_log_mask, bit) & bit) return;
    FILE *f = fopen("C:\\fgo\\_tools\\glshim\\nv_dispatch_inventory_v1.log", "a");
    if (!f) return;
    fprintf(f,
            "pid=%lu frame=%llu event=resolve name=%s family=%s lowering=%s resolution=%s status=%s\\n",
            (unsigned long)GetCurrentProcessId(),
            (unsigned long long)g_frame_count, entry->name, entry->family,
            entry->lowering, api_census_resolution_name(entry->resolution), status);
    fclose(f);
}

static int nv_dispatch_name_ends_nv(const char *name)
{
    size_t n;
    if (!name) return 0;
    n = strlen(name);
    return n >= 2 && name[n - 2] == 'N' && name[n - 1] == 'V';
}

static int nv_dispatch_is_registered(const char *name)
{
    for (unsigned i = 0; i < sizeof(g_nv_dispatch) / sizeof(g_nv_dispatch[0]); i++) {
        if (strcmp(name, g_nv_dispatch[i].name) == 0) return 1;
    }
    return 0;
}

/* Unknown NV ABIs must remain driver-owned.  Record the discovery once, but
   never substitute a generic trampoline for a function we cannot type safely. */
static void nv_dispatch_log_unhandled(const char *name, const char *route)
{
    unsigned slot;
    if (!g_nv_dispatch_inventory_on || !nv_dispatch_name_ends_nv(name)) return;
    if (InterlockedCompareExchange(&g_nv_dispatch_unhandled_lock, 1, 0) != 0) return;
    for (slot = 0; slot < g_nv_dispatch_unhandled_count; slot++) {
        if (strcmp(g_nv_dispatch_unhandled_names[slot], name) == 0) {
            InterlockedExchange(&g_nv_dispatch_unhandled_lock, 0);
            return;
        }
    }
    if (slot < sizeof(g_nv_dispatch_unhandled_names) / sizeof(g_nv_dispatch_unhandled_names[0])) {
        FILE *f;
        strncpy(g_nv_dispatch_unhandled_names[slot], name,
                sizeof(g_nv_dispatch_unhandled_names[slot]) - 1);
        g_nv_dispatch_unhandled_names[slot][sizeof(g_nv_dispatch_unhandled_names[slot]) - 1] = 0;
        g_nv_dispatch_unhandled_count++;
        f = fopen("C:\\fgo\\_tools\\glshim\\nv_dispatch_inventory_v1.log", "a");
        if (f) {
            fprintf(f,
                    "pid=%lu frame=%llu event=resolve name=%s family=unregistered lowering=none resolution=%s status=unhandled_passthrough\\n",
                    (unsigned long)GetCurrentProcessId(),
                    (unsigned long long)g_frame_count, name, route);
            fclose(f);
        }
    }
    InterlockedExchange(&g_nv_dispatch_unhandled_lock, 0);
}

static PROC nv_dispatch_resolve(const char *name, unsigned *resolution)
{
    if (resolution) *resolution = API_RES_MISSING;
    if (!name) return NULL;
    for (unsigned i = 0; i < sizeof(g_nv_dispatch) / sizeof(g_nv_dispatch[0]); i++) {
        const nv_dispatch_entry *entry = &g_nv_dispatch[i];
        if (strcmp(name, entry->name) != 0) continue;
        if (entry->requires_driver_symbol && !real_wglGetProcAddress(name)) {
            nv_dispatch_log_resolution(i, entry, "driver_absent");
            return NULL;
        }
        if (resolution) *resolution = entry->resolution;
        nv_dispatch_log_resolution(i, entry, "handled");
        return entry->handler;
    }
    return NULL;
}

