    if (g_frame_count < g_model_material_state_first_frame ||
        g_frame_count - g_model_material_state_first_frame >=
            MODEL_MATERIAL_STATE_PROBE_FRAMES)
        return;

    FILE *f = fopen(
        "C:\\fgo\\_tools\\glshim\\model_material_state_probe_v1.log", "a");
