/* Diagnostic isolation: retain tile lookup and the rest of the material
   shader, but skip every per-tile light iteration. */
static int rewrite_light_loop_zero(const char *src, int len, char *out, int cap)
{
    static const char pat[] = "int ln = tile.m_count;";
    static const char rep[] = "int ln = 0; /* light_loop_zero_v1 */";
    if (!contains_n(src, len, "struct Tile") ||
        !contains_n(src, len, "g_light_indices") ||
        !contains_n(src, len, pat))
        return -1;

    int pat_len = (int)strlen(pat);
    int rep_len = (int)strlen(rep);
    char *p = out;
    int pos = 0;
    int changed = 0;
    while (pos < len && p < out + cap - 1) {
        if (pos + pat_len <= len &&
            memcmp(src + pos, pat, (size_t)pat_len) == 0) {
            if (p + rep_len >= out + cap) return -1;
            memcpy(p, rep, (size_t)rep_len);
            p += rep_len;
            pos += pat_len;
            changed = 1;
        } else {
            *p++ = src[pos++];
        }
    }
    if (pos != len || p >= out + cap) return -1;
    *p = 0;
    return changed ? (int)(p - out) : -1;
}

