static int rewrite_p700_fs_leftover_opacity_texel0(const char *src, int len,
                                                  char *out, int cap)
{
    static const char assign_pfx[] = "opacity = texture(";
    static const char uv_needle[] = ", opacity_texcoord)";
    static const char gain_end[] = "OPACITY0_GAIN;";
    static const char uni[] =
        "uniform float _amdshim_leftover_opacity_texel0;\n"
        "layout(binding = 31) uniform sampler2D _amdshim_leftover_opacity_named;\n";
    static const char mid[] =
        ", opacity_texcoord).r * OPACITY0_GAIN;\n"
        "\topacity = 1.0;";
    int n_assign = 0;
    int assign_at = -1;
    int tex_open;
    int tex_close;
    int uv_at;
    int gain_at;
    int main_at;
    int ra_at;
    int n_ra;
    int brace_at;
    int depth;
    int i;
    const char *sampler;
    int sampler_len;
    char *p;
    char *end;
    int pos;

    if (!p700_fs_leftover_opacity_texel0_candidate(src, len) || !out || cap <= 0)
        return -1;
    for (i = 0; i + (int)sizeof(assign_pfx) - 1 <= len; i++) {
        if (memcmp(src + i, assign_pfx, sizeof(assign_pfx) - 1) == 0) {
            n_assign++;
            assign_at = i;
        }
    }
    if (n_assign != 1 || assign_at < 0)
        return -1;
    tex_open = assign_at + 10;
    if (tex_open + 8 > len || memcmp(src + tex_open, "texture(", 8) != 0)
        return -1;
    depth = 0;
    tex_close = -1;
    for (i = tex_open; i < len; i++) {
        if (src[i] == '(')
            depth++;
        else if (src[i] == ')') {
            depth--;
            if (depth == 0) {
                tex_close = i;
                break;
            }
        }
    }
    if (tex_close < 0)
        return -1;
    uv_at = -1;
    for (i = tex_open; i + (int)sizeof(uv_needle) - 1 <= tex_close + 1; i++) {
        if (memcmp(src + i, uv_needle, sizeof(uv_needle) - 1) == 0) {
            uv_at = i;
            break;
        }
    }
    if (uv_at < 0)
        return -1;
    sampler = src + tex_open + 8;
    sampler_len = uv_at - (tex_open + 8);
    if (sampler_len <= 8 || sampler_len >= 512)
        return -1;
    gain_at = -1;
    for (i = tex_close; i + (int)sizeof(gain_end) - 1 <= len && i < tex_close + 80; i++) {
        if (memcmp(src + i, gain_end, sizeof(gain_end) - 1) == 0) {
            gain_at = i + (int)sizeof(gain_end) - 1;
            break;
        }
    }
    if (gain_at < 0)
        return -1;
    main_at = -1;
    for (i = 0; i + 10 <= len && i <= assign_at; i++) {
        if (memcmp(src + i, "void main(", 10) == 0)
            main_at = i;
    }
    if (main_at < 0 || main_at > assign_at)
        return -1;
    n_ra = 0;
    ra_at = -1;
    for (i = assign_at; i + 19 <= len; i++) {
        if (memcmp(src + i, "result.a = opacity;", 19) == 0) {
            n_ra++;
            ra_at = i;
        }
    }
    if (n_ra != 1 || ra_at < 0)
        return -1;
    {
        static const char fog_end[] = "#endif//COMPOSITE_VOLUME_FOG";
        int fog_at = -1;
        for (i = ra_at; i + (int)sizeof(fog_end) - 1 <= len; i++) {
            if (memcmp(src + i, fog_end, sizeof(fog_end) - 1) == 0)
                fog_at = i;
        }
        if (fog_at < 0)
            return -1;
        brace_at = fog_at + (int)sizeof(fog_end) - 1;
        while (brace_at < len && (src[brace_at] == ' ' || src[brace_at] == '\t' ||
                                 src[brace_at] == '\r' || src[brace_at] == '\n'))
            brace_at++;
        if (brace_at >= len || src[brace_at] != '}')
            return -1;
    }

    p = out;
    end = out + cap - 1;
    pos = 0;
    while (pos < len && p < end) {
        if (pos == main_at) {
            int ulen = (int)sizeof(uni) - 1;
            if (p + ulen >= end)
                return -1;
            memcpy(p, uni, (size_t)ulen);
            p += ulen;
        }
        if (pos == assign_at) {
            if (p + 18 + sampler_len + (int)sizeof(mid) - 1 >= end)
                return -1;
            memcpy(p, "opacity = texture(", 18);
            p += 18;
            memcpy(p, sampler, (size_t)sampler_len);
            p += sampler_len;
            memcpy(p, mid, sizeof(mid) - 1);
            p += (int)sizeof(mid) - 1;
            pos = gain_at;
            continue;
        }
        if (pos == ra_at) {
            static const char ra_rep[] = "result.a = 1.0;";
            int rlen = (int)sizeof(ra_rep) - 1;
            if (p + rlen >= end)
                return -1;
            memcpy(p, ra_rep, (size_t)rlen);
            p += rlen;
            pos += 19;
            continue;
        }
        if (pos == brace_at) {
            static const char mag[] =
                "result = vec4(1.0, 0.0, 1.0, 1.0);\n";
            int mlen = (int)sizeof(mag) - 1;
            if (p + mlen + 1 >= end)
                return -1;
            memcpy(p, mag, (size_t)mlen);
            p += mlen;
            *p++ = '}';
            pos += 1;
            continue;
        }
        *p++ = src[pos++];
    }
    if (pos != len || p >= end)
        return -1;
    *p = 0;
    return (int)(p - out);
}

