static void save_bmp(const char *path, int w, int h, const unsigned char *rgb)
{
    FILE *f = fopen(path, "wb");
    if (!f) return;
    int row = w * 3;
    int rowpad = (4 - (row % 4)) % 4;
    int data = (row + rowpad) * h;
    int file = 54 + data;
    unsigned char hdr[54];
    memset(hdr, 0, sizeof hdr);
    hdr[0] = 'B'; hdr[1] = 'M';
    hdr[2] = (unsigned char)(file & 0xff); hdr[3] = (unsigned char)((file >> 8) & 0xff);
    hdr[4] = (unsigned char)((file >> 16) & 0xff); hdr[5] = (unsigned char)((file >> 24) & 0xff);
    hdr[10] = 54;
    hdr[14] = 40;
    hdr[18] = (unsigned char)(w & 0xff); hdr[19] = (unsigned char)((w >> 8) & 0xff);
    hdr[20] = (unsigned char)((w >> 16) & 0xff); hdr[21] = (unsigned char)((w >> 24) & 0xff);
    hdr[22] = (unsigned char)(h & 0xff); hdr[23] = (unsigned char)((h >> 8) & 0xff);
    hdr[24] = (unsigned char)((h >> 16) & 0xff); hdr[25] = (unsigned char)((h >> 24) & 0xff);
    hdr[26] = 1;
    hdr[28] = 24;
    fwrite(hdr, 1, 54, f);
    for (int y = h - 1; y >= 0; y--) {
        const unsigned char *src = rgb + (size_t)y * w * 3;
        for (int x = 0; x < w; x++) {
            fputc(src[x * 3 + 2], f); /* B */
            fputc(src[x * 3 + 1], f); /* G */
            fputc(src[x * 3 + 0], f); /* R */
        }
        for (int p = 0; p < rowpad; p++) fputc(0, f);
    }
    fclose(f);
}

static HANDLE pace_timer(void)
{
    static HANDLE timer;
    static int attempted;
    if (!attempted) {
        attempted = 1;
        /* Windows 10 1803+: high-resolution timer, independent of tick rate. */
        timer = CreateWaitableTimerExW(NULL, NULL, 0x00000002,
                                      TIMER_MODIFY_STATE | SYNCHRONIZE);
    }
    return timer;
}

static void pace_wait_until(LARGE_INTEGER *now, LONGLONG deadline, LONGLONG frequency)
{
    HANDLE timer = pace_timer();
    const LONGLONG spin = frequency / 2000; /* Last 0.5 ms absorbs wake jitter. */
    for (;;) {
        LONGLONG remaining = deadline - now->QuadPart;
        if (remaining <= 0) return;
        if (timer && remaining > spin) {
            LARGE_INTEGER due;
            due.QuadPart = -((remaining - spin) * 10000000 / frequency);
            if (!due.QuadPart) due.QuadPart = -1;
            if (SetWaitableTimer(timer, &due, 0, NULL, NULL, FALSE) &&
                WaitForSingleObject(timer, INFINITE) == WAIT_OBJECT_0) {
                QueryPerformanceCounter(now);
                continue;
            }
        }
        if (!timer || remaining > spin) {
            DWORD ms = (DWORD)(remaining * 1000 / frequency);
            if (ms > 1) Sleep(ms - 1);
        }
        YieldProcessor();
        QueryPerformanceCounter(now);
    }
}

/* Keep the established frame boundary and 60 Hz scheduling policy. A late
   frame resets from its actual arrival; it never starts a catch-up burst. */
static void pace_frame_60hz(void)
{
    static LARGE_INTEGER freq;
    static LARGE_INTEGER last;
    LARGE_INTEGER now;
    if (freq.QuadPart == 0) QueryPerformanceFrequency(&freq);
    QueryPerformanceCounter(&now);
    if (last.QuadPart != 0 && freq.QuadPart > 0) {
        const LONGLONG target = freq.QuadPart / 60;
        LONGLONG remaining = target - (now.QuadPart - last.QuadPart);
        if (remaining > 0)
            pace_wait_until(&now, last.QuadPart + target, freq.QuadPart);
    }
    last = now;
}

static void frame_boundary_bookkeeping(void)
{
    battle_observe_arm();

    /* Frame accounting and pacing are required even without capture.
       VAO zero is a state-reset boundary, not a proven presentation
       boundary.  The marker-gated bypass keeps the legacy path reversible. */
    if (!g_no_vao_pacing_on ||
        (g_login_aware_pacing_on && !g_login_aware_home_seen))
        pace_frame_60hz();
    g_frame_count++;
    if (g_skinning_matrix_ring_on) {
        if (!real_matrix_glFenceSync)
            real_matrix_glFenceSync =
                (matrix_glFenceSync_t)trace_resolve("glFenceSync");
        if (!real_matrix_glDeleteSync)
            real_matrix_glDeleteSync =
                (matrix_glDeleteSync_t)trace_resolve("glDeleteSync");
        if (real_matrix_glFenceSync) {
            for (int si = 0; si < g_ubo_scan_n; si++) {
                ubo_scan_entry *ent = &g_ubo_scan[si];
                if (!ent->matrix_ring[0]) continue;
                unsigned ri = ent->matrix_ring_index % 3u;
                GLsync next = real_matrix_glFenceSync(0x9117 /* GL_SYNC_GPU_COMMANDS_COMPLETE */, 0);
                if (next) {
                    if (ent->matrix_ring_fence[ri] && real_matrix_glDeleteSync)
                        real_matrix_glDeleteSync(ent->matrix_ring_fence[ri]);
                    ent->matrix_ring_fence[ri] = next;
                }
            }
        }
    }
    api_census_flush(0);
    bindless_emulation_frame();
    perf_timing_emit();
    material_probe_frame();
    }

